def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water >= 1:
            return min(budget, 45.0)
        return min(budget, 18.0)

    prev_bids = []
    prev_by_id = {}
    eric_prev = None
    urgent_count = 0
    rich_count = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid')
            prev_bids.append(bid)
            prev_by_id[oid] = bid
        if oid == 'Eric' and bid is not None:
            eric_prev = bid
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_count += 1
        if opp.get('budget', 0) >= 100:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = supply <= 17
    ample = supply >= 22
    danger = hp <= 2 or no_water >= 1
    caution = hp <= 4

    bid = 0.0

    if danger:
        anchor = eric_prev if eric_prev is not None else highest_prev
        if scarcity:
            bid = max(78.0, anchor + 4.0)
        else:
            bid = max(62.0, anchor * 0.72 + 6.0)
    elif scarcity:
        if eric_prev is not None:
            bid = max(48.0, eric_prev + 2.5)
        else:
            bid = max(42.0, highest_prev + 2.0)
        if rich_count >= 2:
            bid += 6.0
        if day >= 7:
            bid += 4.0
    elif ample:
        if hp >= 6 and no_water == 0:
            bid = 16.0
        else:
            bid = max(24.0, avg_prev * 0.22)
    else:
        if eric_prev is not None:
            bid = max(28.0, min(58.0, eric_prev * 0.42))
        else:
            bid = max(26.0, min(52.0, avg_prev * 0.55 + 4.0))
        if caution:
            bid += 8.0
        if urgent_count >= 2:
            bid += 5.0

    if day >= 8:
        bid += 6.0
    if budget < 60:
        bid = min(bid, budget)
    else:
        bid = min(bid, budget, 110.0)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Identify alive opponents
    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opponents.append(o)

    # If no opponents, bid conservatively
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only
    yesterday_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Baseline from typical yesterday behavior
    typical_bid = 0.0
    if yesterday_bids:
        typical_bid = sum(yesterday_bids) / float(len(yesterday_bids))
        highest_prev_bid = max(yesterday_bids)
    else:
        highest_prev_bid = 0.0

    # Pressure heuristic: if someone previously bid very high, we must match/beat moderately
    # Use hp to decide how aggressive we can be.
    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Supply pressure: lower supply => bid higher to avoid no-water days
    # Map supply in [15,25] to pressure in [1.0,0.6]
    if MAX_SUPPLY <= MIN_SUPPLY:
        supply_pressure = 1.0
    else:
        t = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
        if t < 0.0:
            t = 0.0
        if t > 1.0:
            t = 1.0
        supply_pressure = 1.0 - 0.4 * t

    no_water_days = int(my_status['no_water_days'])

    # Core target bid
    # If high previous bids exist, aim slightly above typical/highest depending on hp.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Very aggressive field
        if my_hp <= 2.0 or no_water_days >= 1:
            target = max(typical_bid * 1.05, highest_prev_bid * 0.98)
        else:
            target = max(typical_bid * 1.02, highest_prev_bid * 0.85)
    else:
        # Moderate field
        if my_hp <= 2.0 or no_water_days >= 1:
            target = max(typical_bid * 1.08, DAILY_SALARY * 0.7)
        else:
            target = max(typical_bid * 1.03, DAILY_SALARY * 0.55)

    # Adjust by supply pressure
    target = target * float(supply_pressure)

    # Keep within budget and also avoid overpaying late if budget low
    # Use remaining days heuristic lightly: episode_days not provided; rely on day index.
    # If day is late (>=8), be a bit more conservative.
    if day is not None:
        try:
            d = int(day)
        except Exception:
            d = 0
    else:
        d = 0

    if d >= 8:
        target = target * 0.9

    # Final cap: cannot exceed budget
    bid = min(my_budget, target)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    # If bid becomes too small relative to need, enforce a minimum floor
    # (helps when supply is low and hp is critical)
    if my_hp <= 2.0:
        bid = max(bid, min(my_budget, DAILY_SALARY * 0.9))
    elif no_water_days >= 2:
        bid = max(bid, min(my_budget, DAILY_SALARY * 0.75))
    else:
        bid = max(bid, min(my_budget, DAILY_SALARY * 0.5)) if bid == 0.0 else bid

    return bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Get yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine opponent pressure
    if yesterday_bids:
        highest_yesterday = max(yesterday_bids)
        # If any opponent had HP <=2, they might be desperate
        desperate = any(opp['hp'] <= 2 for opp in alive_opponents)
        if desperate:
            # They will likely bid very high; match or exceed if I need water
            if hp <= 2:
                return min(budget, DAILY_SALARY * 0.95)
            else:
                # Bid just below their potential despair bid to save budget
                return min(budget, max(DAILY_SALARY * 0.5, highest_yesterday + 1))
        else:
            # Normal pressure
            if hp <= 2:
                return min(budget, DAILY_SALARY * 0.95)
            elif hp <= 5:
                # Moderate need: bid enough to win against typical high bid
                return min(budget, max(DAILY_SALARY * 0.6, highest_yesterday + 0.5))
            else:
                # High HP: conserve budget
                return min(budget, max(DAILY_SALARY * 0.3, highest_yesterday - 5))
    else:
        # No traces available (maybe first day?)
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.9)
        elif hp <= 5:
            return min(budget, DAILY_SALARY * 0.6)
        else:
            return min(budget, DAILY_SALARY * 0.4)
